    static final String[] METHODS = {"m0", "m1", "m2", "m3", "m4", "m5", "m6", "m7", "m8", "m9", "m10", "m11"};
    static final String[] FIELDS = {"f0", "f1", "f2", "f3"};

    static long round(int salt) throws ReflectiveOperationException {
        long sum = 0;
        for (Class<?> c : CLASSES) {
            sum += c.getDeclaredMethods().length;
            for (Method x : c.getMethods()) {
                if (x.getDeclaringClass() == c) {
                    sum++;
                }
            }
            sum += c.getDeclaredFields().length;
            Method m = c.getMethod(METHODS[salt % 12]);
            sum += m.getName().length();
            Field f = c.getDeclaredField(FIELDS[salt % 4]);
            sum += f.getName().length();
            sum += c.getDeclaredConstructors().length;
        }
        return sum;
    }

    public static void main(String[] args) throws ReflectiveOperationException {
        long sum = 0;
        for (int i = 0; i < 200; i++) {
            sum += round(i);
        }
        long start = System.nanoTime();
        for (int i = 0; i < 2000; i++) {
            sum += round(i);
        }
        System.err.println("kernel-ms " + (System.nanoTime() - start) / 1000000);
        System.out.println(sum);
    }
